import 'dart:convert';import 'dart:math' as math;import 'package:flutter/material.dart';import 'package:flutter/services.dart';import '../models/disease_event.dart';
class KoreaDiseaseMap extends StatefulWidget{final List<DiseaseEvent> events;const KoreaDiseaseMap({super.key,required this.events});@override State<KoreaDiseaseMap> createState()=>_KoreaDiseaseMapState();}
class _KoreaDiseaseMapState extends State<KoreaDiseaseMap>{Map<String,dynamic>? geo;@override void initState(){super.initState();rootBundle.loadString('assets/data/korea_provinces.geojson').then((s){if(mounted)setState(()=>geo=jsonDecode(s));});}@override Widget build(BuildContext context)=>DecoratedBox(decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16)),child:geo==null?const Center(child:CircularProgressIndicator()):CustomPaint(painter:_MapPainter(geo!,widget.events),child:const SizedBox.expand()));}
class _MapPainter extends CustomPainter{final Map<String,dynamic> geo;final List<DiseaseEvent> events;_MapPainter(this.geo,this.events);Offset p(double lon,double lat,Size s){const minLon=124.4,maxLon=132.2,minLat=32.8,maxLat=38.8;return Offset((lon-minLon)/(maxLon-minLon)*s.width,(maxLat-lat)/(maxLat-minLat)*s.height);}void ring(Canvas c,List pts,Size s,Paint paint){final path=Path();for(var i=0;i<pts.length;i++){final a=pts[i] as List;final o=p((a[0] as num).toDouble(),(a[1] as num).toDouble(),s);i==0?path.moveTo(o.dx,o.dy):path.lineTo(o.dx,o.dy);}path.close();c.drawPath(path,paint);}@override void paint(Canvas c,Size s){final fill=Paint()..color=const Color(0xffeef1f2)..style=PaintingStyle.fill;final line=Paint()..color=Colors.white..strokeWidth=1..style=PaintingStyle.stroke;for(final f in (geo['features'] as List)){final g=f['geometry'];final coords=g['coordinates'] as List;if(g['type']=='Polygon'){for(final r in coords){ring(c,r as List,s,fill);ring(c,r,s,line);}}else if(g['type']=='MultiPolygon'){for(final poly in coords){for(final r in poly as List){ring(c,r as List,s,fill);ring(c,r,s,line);}}}}for(final e in events){if(e.latitude==null||e.longitude==null)continue;final o=p(e.longitude!,e.latitude!,s);c.drawCircle(o,5,Paint()..color=Colors.redAccent);}}@override bool shouldRepaint(covariant _MapPainter old)=>true;}
